// 1) BEST — the framework moves to the edges and the logic becomes a plain JVM test
interface Logger { fun d(tag: String, message: String) }
object NoopLogger : Logger { override fun d(tag: String, message: String) = Unit }

class LinkParser(private val logger: Logger) {
  fun orderId(link: String): Long? {
    logger.d("DeepLink", "parsing $link")
    return URI(link).query
      ?.split("&")
      ?.firstOrNull { it.startsWith("order=") }
      ?.removePrefix("order=")
      ?.toLongOrNull()
  }
}

