// ❌ Two acts, a boolean assertion, a name that describes the method
class CartTest {
  @Test fun testCart() {
    val cart = Cart()
    cart.add(Item("apple", cents = 100))
    cart.applyCoupon("HALF")
    assertTrue(cart.totalCents == 50)          // expected:<false> but was:<true>
    cart.clear()
    assertTrue(cart.isEmpty())                 // never reached once the first goes red
  }
}

// ✅ One subject per test, values in the message, the act on one line
class CartTotalTest {

  private fun cart(vararg items: Item) = Cart().apply { items.forEach(::add) }

  @Test fun `coupon halves the total`() {
    val cart = cart(Item("apple", cents = 100))       // given

    cart.applyCoupon("HALF")                          // when

    assertEquals(50, cart.totalCents)                 // then: expected:<50> but was:<100>
  }

  @Test fun `clearing empties the cart`() {
    val cart = cart(Item("apple", cents = 100))

    cart.clear()

    assertThat(cart.items).isEmpty()                  // Truth names what was left behind
  }

  @Test fun `unknown coupon leaves the total alone`() {
    val cart = cart(Item("apple", cents = 100))

    cart.applyCoupon("NOPE")

    // ❌ assertEquals(cart.totalCents, 100) — reversed, so a failure reads backwards
    assertEquals(100, cart.totalCents)
  }
}

class OrderRepo(private val api: Api, private val dao: OrderDao) {   // final, as Kotlin is
  suspend fun load(id: Long): Order = dao.byId(id) ?: api.fetch(id).also { dao.insert(it) }
  suspend fun archive(order: Order) { dao.insert(order.copy(archived = true)) }
}

class ArchiveUseCaseTest {
  private val repo = mockk<OrderRepo>(relaxUnitFun = true)   // only Unit funs are relaxed

  @Test fun `archives the loaded order`() = runTest {
    coEvery { repo.load(7) } returns Order(id = 7, archived = false)   // coEvery, not every
    val slot = slot<Order>()
    coEvery { repo.archive(capture(slot)) } just Runs

    ArchiveUseCase(repo).invoke(id = 7)

    coVerify(exactly = 1) { repo.archive(any()) }
    assertTrue(slot.captured.archived)                      // assert the argument, not the call
  }

  @After fun tearDown() = unmockkAll()                      // mandatory once statics are involved
}

// The stateful collaborator is cheaper as a fake: one file, reused by every test,
// and it fails when the behaviour is wrong rather than when a method is renamed.
class FakeOrderRepo(initial: List<Order> = emptyList()) : OrderRepository {
  private val rows = MutableStateFlow(initial.associateBy(Order::id))
  var loadCount = 0
    private set

  override fun observe(): Flow<List<Order>> = rows.map { it.values.toList() }

  override suspend fun load(id: Long): Order {
    loadCount++
    return rows.value[id] ?: error("no order $id")
  }

  override suspend fun archive(order: Order) {
    rows.update { it + (order.id to order.copy(archived = true)) }
  }
}

class SearchViewModelTest {
  @get:Rule val mainRule = MainDispatcherRule()      // StandardTestDispatcher on Main

  // ❌ a StateFlow never completes, so this waits for an event that cannot happen
  @Test fun hangsForever() = runTest {
    val states = SearchViewModel(FakeRepo()).state.toList()
    assertEquals(2, states.size)
  }

  // ✅ one event at a time, and a timeout instead of a dead runner
  @Test fun `emits loading then results`() = runTest {
    val vm = SearchViewModel(FakeRepo(delayMs = 500))

    vm.state.test {
      assertEquals(UiState.Empty, awaitItem())       // the replayed current value
      vm.search("room")
      assertEquals(UiState.Loading, awaitItem())

      advanceTimeBy(501)                             // virtual time, nothing sleeps
      assertTrue(awaitItem() is UiState.Results)

      expectNoEvents()                               // a fourth emission would be a bug
      cancelAndIgnoreRemainingEvents()
    }
  }

  // A replay-0 SharedFlow drops what was emitted before collection began,
  // and two flows in one test need turbineScope.
  @Test fun `retry emits a one-off event`() = runTest {
    val vm = SearchViewModel(FakeRepo())
    turbineScope {
      val states = vm.state.testIn(backgroundScope)
      val events = vm.events.testIn(backgroundScope) // collecting from this line on

      vm.retry()
      advanceUntilIdle()

      assertEquals(UiEvent.Retried, events.awaitItem())
      events.cancel()
      states.cancelAndIgnoreRemainingEvents()
    }
  }
}

class MainDispatcherRule(
  val dispatcher: TestDispatcher = StandardTestDispatcher(),
) : TestWatcher() {
  override fun starting(d: Description) = Dispatchers.setMain(dispatcher)
  override fun finished(d: Description) = Dispatchers.resetMain()
}

class ProfileViewModel(repo: Repo) : ViewModel() {
  private val _state = MutableStateFlow<UiState>(UiState.Loading)
  val state: StateFlow<UiState> = _state
  init { viewModelScope.launch { _state.value = UiState.Loaded(repo.profile()) } }
}

class ProfileViewModelTest {
  @get:Rule val mainRule = MainDispatcherRule()      // Standard: launches are queued

  @Test fun `green only because the coroutine ran too early`() = runTest {
    val vm = ProfileViewModel(FakeRepo())
    // Under UnconfinedTestDispatcher init's launch has already finished here, so this
    // passes — and hides that the first frame on a device renders Loading.
    assertTrue(vm.state.value is UiState.Loaded)     // red under Standard, correctly
  }

  @Test fun `the honest version asserts both states`() = runTest {
    val vm = ProfileViewModel(FakeRepo(delayMs = 200))

    assertEquals(UiState.Loading, vm.state.value)    // what the user sees first
    advanceTimeBy(200)                               // tasks AT 200 ms have not run yet
    assertEquals(UiState.Loading, vm.state.value)
    runCurrent()                                     // ...this one runs them
    assertTrue(vm.state.value is UiState.Loaded)
    assertEquals(200, currentTime)                   // 200 ms virtual, 0 ms real
  }
}

