class OrderViewModel(
  savedState: SavedStateHandle,
  strings: StringProvider,                       // an interface, not a Context
  private val repo: OrderRepository,
) : ViewModel(), DefaultLifecycleObserver {
  val orderId: Long = checkNotNull(savedState["orderId"])
  val title: StateFlow<String> = savedState.getStateFlow("title", strings.get(R.string.untitled))
  override fun onStart(owner: LifecycleOwner) { repo.startPolling(orderId) }
}

class OrderViewModelTest {
  @get:Rule val mainRule = MainDispatcherRule()

  @Test fun `the argument arrives through the handle, not a setter`() = runTest {
    val vm = OrderViewModel(
      savedState = SavedStateHandle(mapOf("orderId" to 42L)),   // plain constructor
      strings = FakeStrings(R.string.untitled to "Untitled"),
      repo = FakeOrderRepository(),
    )

    assertEquals(42L, vm.orderId)
    assertEquals("Untitled", vm.title.value)
  }

  @Test fun `the observer fires only because the test drives the lifecycle`() = runTest {
    val repo = FakeOrderRepository()
    val vm = OrderViewModel(SavedStateHandle(mapOf("orderId" to 1L)), FakeStrings(), repo)

    val owner = TestLifecycleOwner(Lifecycle.State.INITIALIZED, mainRule.dispatcher)
    owner.lifecycle.addObserver(vm)
    assertEquals(0, repo.pollCount)                  // nothing has happened yet

    owner.setCurrentState(Lifecycle.State.STARTED)   // ON_CREATE, then ON_START
    assertEquals(1, repo.pollCount)
  }
}

