// Ships inside the app; the release variant provides a no-op counter
object AppIdling {
  val network = CountingIdlingResource("network")
}

class SearchRepository(private val api: Api) {
  suspend fun search(q: String): List<Book> {
    AppIdling.network.increment()
    try {
      return api.search(q)
    } finally {
      AppIdling.network.decrement()   // in finally, or one failed call hangs the suite
    }
  }
}

