class OrdersScreenTest {
  @get:Rule val rule = createComposeRule()
  private val repo = FakeOrderRepo()

  // ❌ hangs: the indicator animates forever, so the implicit idle wait never returns
  @Test fun showsContent_hangs() {
    rule.setContent { AppTheme { OrdersScreen(OrdersViewModel(repo)) } }
    rule.onNodeWithText("Order 42").assertIsDisplayed()   // times out after 60s
  }

  @Test fun spinnerThenContent() {
    rule.mainClock.autoAdvance = false          // the test owns time from here on
    rule.setContent { AppTheme { OrdersScreen(OrdersViewModel(repo)) } }

    rule.onNodeWithTag("loading").assertIsDisplayed()     // returns, nothing waits for idle

    repo.emit(listOf(Order(42, "Socks", "12.00 €")))
    rule.mainClock.advanceTimeByFrame()                   // one frame: let it recompose
    rule.onNodeWithText("Order 42").assertIsDisplayed()

    // assert the middle of the enter transition, not just its end state
    rule.mainClock.advanceTimeBy(150)
    rule.onNodeWithTag("undo-banner").assertIsDisplayed()
  }

  // Work you do not control: poll a condition instead of sleeping
  @Test fun waitsForRealWork() {
    rule.setContent { AppTheme { OrdersScreen(OrdersViewModel(realRepo)) } }
    rule.waitUntil(timeoutMillis = 5_000) {
      rule.onAllNodesWithTag("order-row").fetchSemanticsNodes().isNotEmpty()
    }
    rule.onAllNodesWithTag("order-row").assertCountEquals(3)
  }
}

