@RunWith(AndroidJUnit4::class)
class UploadWorkTest {
  private val context: Context = ApplicationProvider.getApplicationContext()

  @Before fun setUp() {
    val config = Configuration.Builder()
      .setExecutor(SynchronousExecutor())        // runs on the calling thread
      .setMinimumLoggingLevel(Log.DEBUG)
      .build()
    WorkManagerTestInitHelper.initializeTestWorkManager(context, config)
  }

  // Level 1: the worker is just a class — no scheduler in sight
  @Test fun retriesOnServerError() = runBlocking {
    fakeApi.failNext(503)
    val worker = TestListenableWorkerBuilder<UploadWorker>(context)
      .setInputData(workDataOf("path" to "/tmp/a.jpg"))
      .build()

    assertEquals(ListenableWorker.Result.retry(), worker.doWork())
  }

  // Level 2: prove the constraint actually gates it
  @Test fun waitsForUnmeteredNetwork() {
    val request = OneTimeWorkRequestBuilder<UploadWorker>()
      .setConstraints(
        Constraints.Builder().setRequiredNetworkType(NetworkType.UNMETERED).build()
      )
      .build()
    val wm = WorkManager.getInstance(context)
    wm.enqueueUniqueWork("upload", ExistingWorkPolicy.KEEP, request).result.get()

    assertEquals(WorkInfo.State.ENQUEUED, wm.getWorkInfoById(request.id).get()!!.state)

    WorkManagerTestInitHelper.getTestDriver(context)!!.setAllConstraintsMet(request.id)

    // synchronous executor: it has already run by the time the call returns
    assertEquals(WorkInfo.State.SUCCEEDED, wm.getWorkInfoById(request.id).get()!!.state)
  }

  // A receiver needs no framework at all
  @Test fun schedulesSyncOnConnectivity() {
    ConnectivityReceiver(scheduler = fakeScheduler)
      .onReceive(context, Intent(ConnectivityManager.CONNECTIVITY_ACTION))
    assertTrue(fakeScheduler.syncRequested)
  }
}

// The unit under test: one boundary, one off-by-one waiting to happen
class Basket(private val items: List<Item>) {
  fun shippingCost(): Long =
    if (items.sumOf { it.cents } > FREE_SHIPPING_CENTS) 0L else FLAT_RATE_CENTS
}

// ❌ 100% line coverage, zero information: it runs the method and asserts a type
