  assertNotNull(Basket(listOf(Item(cents = 500))).shippingCost())
}

// Pitest mutates `>` into `>=` and this test still passes, so the mutant SURVIVES.
// That report line is the coverage number admitting the branch is unchecked.

// ✅ pin the boundary from both sides — now `>` -> `>=` kills the mutant
@RunWith(Parameterized::class)
class ShippingBoundaryTest(private val cents: Long, private val expected: Long) {

  @Test fun shippingCost() {
    assertEquals(expected, Basket(listOf(Item(cents))).shippingCost())
  }

  companion object {
    @JvmStatic
    @Parameterized.Parameters(name = "{0} cents -> {1}")
    fun cases() = listOf(
      arrayOf(4_999L, FLAT_RATE_CENTS),   // just below
      arrayOf(5_000L, FLAT_RATE_CENTS),   // exactly at the threshold: the mutant's home
      arrayOf(5_001L, 0L),                // just above
    )
  }
}

